disclaimer_ui <- function() shiny::div(class="disclaimer",hcf_disclaimer)
mod_player_input_ui <- function(id) { ns<-shiny::NS(id); shiny::tagList(shiny::h3("Daily player entry"),shiny::fluidRow(shiny::column(4,shiny::selectInput(ns("player"),"Player",NULL),shiny::dateInput(ns("date"),"Date"),shiny::numericInput(ns("training"),"Training duration (minutes)",60,min=0),shiny::numericInput(ns("match"),"Match minutes played (minutes; 0 if none)",0,min=0),shiny::numericInput(ns("overs"),"Overs bowled (count)",0,min=0)),shiny::column(4,shiny::numericInput(ns("sleep"),"Sleep duration (hours, e.g. 7.5)",7.5,min=0),shiny::numericInput(ns("wellness"),"Subjective wellness score (1–10)",7,min=1,max=10),shiny::numericInput(ns("age"),"Age (years)",27,min=16),shiny::checkboxInput(ns("history"),"Prior injury history (any)")),shiny::column(4,shiny::numericInput(ns("hid"),"High-intensity distance (m; optional)",NA),shiny::numericInput(ns("sprints"),"Sprint count (optional)",NA),shiny::numericInput(ns("speed"),"Bowling speed (km/h; optional)",NA),shiny::numericInput(ns("rpe"),"Session RPE (1–10; optional)",NA),shiny::numericInput(ns("soreness"),"Muscle soreness (1–5; optional)",NA),shiny::numericInput(ns("recovery"),"Recovery score (0–100; optional)",NA))),shiny::actionButton(ns("save"),"Save daily entry"),shiny::verbatimTextOutput(ns("status"))) }
mod_player_input_server <- function(id,con) shiny::moduleServer(id,function(input,output,session){ observe({ p<-db_players(con); shiny::updateSelectInput(session,"player",choices=setNames(p$player_id,p$player_name)) }); observeEvent(input$save,{ req(input$player); e<-list(player_id=input$player,date=as.character(input$date),training_minutes=input$training,match_minutes=input$match,overs_bowled=input$overs,sleep_hours=input$sleep,wellness_score=input$wellness,age=input$age,prior_injury=as.integer(input$history),high_intensity_distance=input$hid,sprint_count=input$sprints,bowling_speed=input$speed,session_rpe=input$rpe,muscle_soreness=input$soreness,recovery_score=input$recovery,rest_days=3,z_team=0,injury_event=0); db_save_entry(con,e); output$status<-shiny::renderText("Saved. Optional blanks use population defaults during estimation.") }) })
mod_dashboard_ui <- function(id) { ns<-shiny::NS(id); shiny::tagList(shiny::selectInput(ns("player"),"Player",NULL),shiny::actionButton(ns("run"),"Run 7-day availability analysis"),shiny::uiOutput(ns("summary")),DT::DTOutput(ns("scenarios")),disclaimer_ui()) }
mod_dashboard_server <- function(id,con,cfg) shiny::moduleServer(id,function(input,output,session){ observe({p<-db_players(con);shiny::updateSelectInput(session,"player",choices=setNames(p$player_id,p$player_name))}); result<-shiny::eventReactive(input$run,{d<-db_entries(con,input$player);req(nrow(d)>=2); p<-db_players(con);pl<-p[p$player_id==input$player,]; d$z_team<-d$z_team%||%0; d$injury_event<-d$injury_event%||%0; d$muscle_soreness[is.na(d$muscle_soreness)]<-cfg$default_optional$soreness; d$recovery_score[is.na(d$recovery_score)]<-cfg$default_optional$recovery_score; # Fast interactive filter; full MIF remains admin-gated.
fit<-fit_player_pomp(d,cfg,particles=300,run_mif=FALSE); state<-fit$current_state; reference<-cfg$state_reference; forcing<-construct_forcing(d,cfg); idx<-tail(seq_len(nrow(d)),min(cfg$horizon_days,nrow(d))); plan<-data.frame(w_true=forcing$w[idx],r_true=forcing$r[idx],z_team=forcing$zteam[idx]); ans<-decision_support(state,plan,pl,reference,cfg,paths=cfg$monte_carlo_paths);db_cache_output(con,input$player,Sys.Date(),ans);ans}); output$summary<-shiny::renderUI({x<-result();shiny::tagList(shiny::h3(sprintf("%s-day risk: %.1f%% (%s)",x$horizon_days,100*x$baseline_probability,x$risk_tier)),shiny::p(sprintf("Marginal risk (+10%% workload): %+0.1f percentage points",100*x$marginal_risk_per_10pct)))});output$scenarios<-DT::renderDT({x<-result();show<-x$scenarios;show$injury_probability<-sprintf("%.1f%%",100*show$injury_probability);DT::datatable(show,rownames=FALSE,options=list(dom='t'))}) })
